/**
 * Inline status callout (`design/components/alert.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/alert.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  ResolvedSlot,
  agentMember,
  claimSlot,
  createCell,
  elementRef,
  focusAfterRemoval,
  resolveSlot,
  scope,
  useDeparture,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/alert.module.css'
import Button from '../controls/Button'

export type AlertTone = NonNullable<AlertProps['tone']>

export interface AlertProps {
  /**
   * The first action: one `ghost`/`soft` `sm` Button, such as Apply.
   */
  action?: JSX.Element
  /**
   * The body copy. With no title and no content the Alert renders nothing.
   */
  children?: JSX.Element
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  dismissLabel?: string
  /**
   * `false` hides the tone glyph, for dense stacks where the wash already shows the tone.
   */
  icon?: false
  /**
   * Renders the ✕, and is called after the row has closed so the app can unmount it.
   */
  onDismiss?: () => void
  /**
   * The second action: one `ghost` `sm` Button after `action`, such as Discard. Two is the most
   * an Alert takes; content that needs more is a Card.
   */
  secondaryAction?: JSX.Element
  /**
   * The first line. An empty title counts as no title.
   */
  title?: string
  tone?: 'info' | 'warning' | 'success' | 'danger'
}

/** Inline status callout. */
export default function Alert(given: AlertProps): JSX.Element {
  const props = mergeProps(
    { tone: 'info', dismissLabel: 'Dismiss' } as Defaults<AlertProps, 'tone' | 'dismissLabel'>,
    claimSlot(given),
  )
  return scope(() => {
    const closeRegion = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const childrenSlot = resolveSlot(() => props.children)
    const settle = createCell(undefined as (() => void) | undefined)
    const departure = useDeparture(() => root.value, 'alert.dismiss')
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      void undefined
      release1 = () => {
        settle.value?.()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = focusAfterRemoval(root.value)
      release2 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => root.value),
      effect2,
      true,
    )
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'Alert',
        element: () => root.value,
        state: () => ({
          tone: props.tone,
          title: props.title ?? '',
          dismissible: props.onDismiss !== undefined,
        }),
        actions: {
          dismiss: () =>
            (() => {
              if (!(props.onDismiss !== undefined))
                throw new Error('This alert has no dismiss control.')
              return new Promise<void>((resolve) => {
                settle.value = () => {
                  settle.value = undefined
                  resolve()
                }
                departure.start(() => {
                  props.onDismiss?.()
                  settle.value?.()
                })
              })
            })(),
        },
        withholds: () => closeRegion.value,
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {(props.title !== undefined && props.title !== '') || childrenSlot.filled() ? (
          <ResolvedSlot of={() => props.action}>
            {(actionSlot) => (
              <ResolvedSlot of={() => props.secondaryAction}>
                {(secondaryActionSlot) => (
                  <div
                    class={styles.alert}
                    role={props.tone === 'warning' || props.tone === 'danger' ? 'alert' : 'status'}
                    data-tone={props.tone}
                    data-state={departure.active ? 'closed' : undefined}
                    data-member="alert"
                    ref={root.attach}
                  >
                    {/* panel */}
                    <div class={styles.panel}>
                      {props.icon !== false ? (
                        <span class={styles.glyph}>
                          <Icon name={props.tone === 'danger' ? 'error' : props.tone} />
                        </span>
                      ) : null}
                      {/* body */}
                      <div class={styles.body}>
                        {props.title !== undefined && props.title !== '' ? (
                          <p class={styles.title}>{props.title}</p>
                        ) : null}
                        {childrenSlot.filled() ? (
                          <div class={styles.text}>{childrenSlot()}</div>
                        ) : null}
                        {actionSlot.filled() || secondaryActionSlot.filled() ? (
                          <div class={styles.action}>
                            {actionSlot()}
                            {secondaryActionSlot()}
                          </div>
                        ) : null}
                      </div>
                      {props.onDismiss !== undefined ? (
                        <div class={styles.close} ref={closeRegion.attach}>
                          <Button
                            variant="ghost"
                            tone="neutral"
                            size="sm"
                            iconOnly={true}
                            icon="close"
                            label={props.dismissLabel}
                            onClick={() =>
                              departure.start(() => {
                                props.onDismiss?.()
                                settle.value?.()
                              })
                            }
                          />
                        </div>
                      ) : null}
                    </div>
                  </div>
                )}
              </ResolvedSlot>
            )}
          </ResolvedSlot>
        ) : null}
      </>
    )
  })
}
